INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108316, 'spa', 'Tortas especiales', '2 Samuel 13:6, 8, 10 relata la petición de Amnón y la preparación de las לְבִבוֹת por Tamar. El versículo 8 describe el proceso: ''tomó masa, la amasó, hizo las tortas delante de él y las coció.'' La repetición enfatiza tanto la especificidad del pedido como la diligente obediencia de Tamar. La conexión con la raíz ''corazón'' puede indicar la forma o bien un carácter sustancioso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108317, 'spa', 'Blanquear o purificar', 'Volverse blanco, mostrar blancura o hacer blanco, abarcando tanto la blancura fisica como la purificacion moral metaforica. El Hifil en Is 1:18 y Sal 51:7 describe la promesa divina de hacer los pecados blancos como la nieve, poderosa imagen del perdon. En Dn 11:35 y 12:10 el Hitpael reflexivo transmite la autopurificacion en un proceso escatologico de refinamiento, paralelo a ''refinar'' y ''purgar''. Joel 1:7 usa el sentido fisico literal: ramas descortezadas que muestran su blancura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108318, 'spa', 'Fabricación de ladrillos', 'Génesis 11:3 capta el entusiasmo de los constructores de Babel: ''hagamos ladrillos'' (נִלְבְּנָה לְבֵנִים), usando verbo y acusativo cognado para máximo énfasis. Éxodo 5:7 registra la orden opresiva del Faraón: ''ya no daréis paja al pueblo para hacer ladrillos'' (לִלְבֹּן הַלְּבֵנִים), y el versículo 14 menciona la cuota. El infinitivo constructo indica propósito dentro de un régimen de trabajo forzado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108319, 'spa', 'El color blanco como propiedad visible de objetos, animales, afecciones cutáneas', 'El color blanco como propiedad visible de objetos, animales, afecciones cutáneas y vestiduras. Domina el vocabulario diagnóstico de enfermedades de la piel en Levítico, donde manchas y cabellos blancos determinan el estado ritual (Lv 13:3-4, 10, 13, 19-26). También describe las varas peladas de Jacob (Gn 30:37), la apariencia del maná (Éx 16:31), los dientes de Judá blancos como la leche (Gn 49:12), los caballos visionarios de Zacarías (Zac 1:8; 6:3) y las vestiduras festivas de Eclesiastés 9:8.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108325, 'spa', 'Labán (persona)', 'Labán (persona): el nombre propio Labán (לָבָן, ''blanco''), hijo de Betuel y nieto de Nacor, conocido principalmente como padre de Lea y Raquel, y como suegro y patrón de Jacob en Padán-Aram (Gn 29–31). También aparece como hermano de Rebeca en la narrativa del desposorio (Gn 24:29–50). Las 54 apariciones se refieren a este único patriarca; el epíteto ''el arameo'' (ha-Arammi) en varios pasajes subraya su identidad extranjera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108335, 'spa', 'Libná', 'Libná. Una ciudad cananea en la Sefela de Judá conquistada por Josué (Jos 10:29-39), asignada como ciudad levítica (Jos 21:13) e históricamente significativa durante la monarquía como lugar de origen de madres reales y como objetivo de campañas asirias (2 R 19:8). También designa un campamento en el desierto (Nm 33:20-21). El nombre probablemente refleja el terreno de piedra caliza blanca; la Septuaginta lo traduce consistentemente como Lebna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108340, 'spa', 'Luna poética', 'Cantares 6:10 alaba a la amada: ''hermosa como la luna'' (יָפָה כַלְּבָנָה), en paralelo con ''radiante como el sol'', enlazando belleza celestial y humana. Isaías 24:23 profetiza que ''la luna se avergonzará'' (וְחָפְרָה הַלְּבָנָה) cuando YHWH reine desde Sion, eclipsando todo luminar. Isaías 30:26 promete que ''la luz de la luna será como la luz del sol'', señalando restauración cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108341, 'spa', 'Ladrillo, baldosa', 'Ladrillo de construccion hecho de arcilla moldeada, a menudo secado al sol pero a veces cocido en horno, usado en toda Mesopotamia y Egipto. Los constructores de la Torre de Babel sustituyen piedra por ladrillo (Gn 11:3), y los esclavos israelitas en Egipto son obligados a producir ladrillos bajo cuotas brutales (Ex 1:14; 5:7-8, 14, 16, 18-19). La jactancia desafiante de Isaias — ''los ladrillos cayeron, pero edificaremos con piedra labrada'' (Is 9:9) — capta la arrogancia humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108349, 'spa', 'Líbano (región geográfica)', 'Líbano (región geográfica): el topónimo que designa la cadena montañosa al norte de Israel, empleado tanto como nombre de lugar literal (Dt 1:7; Jos 1:4; 1 R 5:13) como símbolo poético de majestuosidad, fertilidad y fragancia (Sal 29:6; Cnt 4:11, 15; Is 35:2). El vínculo etimológico con לָבָן (''blanco'') evoca cumbres nevadas o acantilados de caliza pálida. Todos los idiomas de destino — español ''Líbano'', francés ''Liban'', alemán ''Libanon'' — conservan el topónimo con mínima adaptación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108364, 'spa', 'Nombre propio levitico', 'El nombre personal Libni, que identifica a un levita hijo de Gerson y nieto de Levi, ancestro eponimo de un subclan levitico. Ex 6:17 y Nm 3:18 lo enumeran junto a su hermano Simei como los dos hijos de Gerson. El Cronista traza sus descendientes a lo largo de varias generaciones en 1 Cr 6:17, 20 y 29. El nombre deriva de la raiz לבן (''ser blanco''), posiblemente reflejando alguna caracteristica fisica o geografica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108366, 'spa', 'vestido de (participio Qal)', 'El participio Qal funcionando como adjetivo estativo: vestido de, ataviado con, cubierto de. En lugar de describir la acción de vestirse, este sentido describe el estado resultante. Aparece de modo prominente en las visiones de Ezequiel —el varón vestido de lino (Ez 9:2-3, 10:2)— y en Pr 31:21 describiendo a la mujer virtuosa cuyo hogar está vestido de escarlata.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108367, 'spa', 'vestir a otro (Hifil)', 'El Hifil causativo: vestir a otra persona, ataviarlo. Teológicamente significativo desde su primera aparición, cuando Dios viste a los primeros humanos (Gn 3:21), este sentido aparece en la investidura real (Gn 41:42), el cuidado materno (Gn 27:15-16) y el simbolismo profético. El lenguaje de ordenación sacerdotal (Éx 28:41) depende fundamentalmente de esta forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108368, 'spa', 'ponerse, vestirse (Qal)', 'El sentido activo Qal: ponerse, llevar o vestir una prenda. El sujeto se viste a sí mismo. Cubre la mayoría de las ocurrencias y abarca desde vestirse cotidianamente (Gn 28:20) hasta la investidura sacerdotal (Lv 6:10-11) y la vestidura metafórica con atributos como justicia o fortaleza. La variedad de objetos vestidos —lino, cilicio, vestiduras reales— muestra la versatilidad del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108374, 'spa', 'ser vestido (Pual)', 'El Pual pasivo: ser vestido, haber sido ataviado por otro. Este pasivo intensivo enfatiza el estado consumado de haber sido vestido, a menudo en contextos ceremoniales. Las atestiguaciones se agrupan en Crónicas y Reyes: sacerdotes vestidos de lino blanco en la dedicación del templo (2 Cr 5:12), reyes sentados ataviados con sus mantos (1 R 22:10). La voz pasiva subraya la dignidad conferida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108437, 'spa', 'Vestir de púrpura', 'Daniel 5:7 registra la proclamación del rey: «vestirá púrpura» (יִלְבַּשׁ אַרְגְּוָנָא), prometiendo vestiduras reales al intérprete. El versículo 16 repite la promesa y el 29 la cumple en forma Hafel: «vistieron a Daniel de púrpura» (הַלְבִּשׁוּ לְדָנִיֵּאל אַרְגְּוָנָא). La repetición subraya la solemnidad del honor prometido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108438, 'spa', 'Medida de liquido', 'Unidad de medida para liquidos (aproximadamente un doceavo de hin, o cerca de medio litro), usada exclusivamente para medir aceite en el ritual de purificacion del leproso en Levitico 14. Las cinco apariciones especifican aceite: Lv 14:10 y 14:21 prescriben ''un log de aceite'' como parte de la ofrenda; 14:12 lo presenta como ofrenda mecida; 14:15 y 14:24 describen al sacerdote vertiendo del log en su palma para la uncion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108439, 'spa', 'Ciudad de Lod', 'Lod aparece en contextos genealógicos y censales. El benjaminita Semed edificó ''Lod con sus aldeas'' (1Cr 8:12). Dos censos postexílicos registran a ''los hijos de Lod'' (sus habitantes): 725 regresaron con Zorobabel (Esd 2:33; Neh 7:37), y la ciudad figura entre los asentamientos benjaminitas en tiempos de Nehemías (Neh 11:35). La Septuaginta la traduce como Lōd, Lod, Luddōn y Lida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108440, 'spa', 'hoja de arma', 'La hoja o filo cortante de un arma, que extiende la noción central de superficie brillante, afilada y peligrosa del fuego al metal. Jue 3:22 es el pasaje definitorio, donde tanto la empuñadura como la hoja (hallahab) de la daga de Ehud desaparecen en Eglón. Job 39:23 describe el destello de una lanza y Nah 3:3 habla del filo centelleante de la espada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108441, 'spa', 'llama, llamarada', 'Llama o llamarada de fuego, que aparece frecuentemente en constructo con ''fuego'' (lahab esh) en escenas de juicio divino, teofanía e imágenes naturales. La llama del altar se eleva al cielo con el ángel del SEÑOR en Jue 13:20; Isaías la emplea tres veces para describir el juicio consumidor de Dios junto con torbellino, trueno y granizo (Isa 29:6; 30:30; 66:15). Joel 2:5 compara el crepitar de las langostas con el de la llama.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108449, 'spa', 'Llama, llamarada', 'Llama, llamarada. Llama o llamarada en su sentido primario: el fuego como fenómeno visible y luminoso. Esto cubre 18 de las 19 apariciones, abarcando fuego literal, teofanía e imaginería de juicio. La zarza ardiente (Éx 3:2) y los relámpagos mezclados con granizo (Sal 105:32) representan la llama literal; la ''llama de fuego'' que devora bosques (Sal 83:14; Jl 2:3) y consume la paja (Is 5:24) sirve como metáfora del juicio divino. En Isaías 47:14 no hay quien se libre de la llama.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108456, 'spa', 'Hoja de un arma', 'Hoja de un arma. La hoja reluciente de un arma, una extensión metafórica del destello y brillo de la llama a la superficie brillante del metal pulido. Este sentido aparece únicamente en 1 Samuel 17:7, describiendo la punta o la hoja de la lanza de Goliat. El español ''hoja'' (hoja/filo) refleja el salto conceptual del fuego al destello metálico, un desarrollo semántico atestiguado en muchas lenguas donde ''llama'' y ''filo'' comparten campo léxico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108466, 'spa', 'abrasar, incendiar', 'Piel: abrasar, incendiar, consumir con fuego en sentido transitivo y causativo. El sujeto —generalmente fuego o llama como instrumento del juicio divino— enciende y devora activamente su objeto. Deuteronomio 32:22 presenta la ira de Dios como fuego que abrasa los cimientos de los montes. Joel 1:19 y 2:3 describen la llama consumiendo los pastizales del desierto. Salmo 106:18 narra el fuego ardiendo entre los rebeldes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108471, 'spa', 'arder, llamear', 'Qal: arder, llamear — sentido intransitivo y estativo que describe algo en estado de combustión. En Sal 104:4 Dios hace del ''fuego llameante'' sus ministros, y en Sal 57:4 los enemigos son descritos como ''los que arden'', metáfora vívida de hostilidad destructiva. Las dos apariciones en Qal emplean el participio activo, otorgando al verbo una cualidad adjetival cercana a ''llameante''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108479, 'spa', 'Por tanto', 'En Rut 1:13 Noemí razona dos veces con הֲלָהֵן («¿acaso por tanto...?»), introduciendo la consecuencia de sus preguntas retóricas: lo irrazonable de esperar. Job 30:24 es debatido; algunos leen לָהֵן como «a ellos» y otros ven dificultad textual. La forma coincide con el arameo לָהֵן de Daniel 2:6, 9 y 4:24.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108480, 'spa', 'Excepto, a menos que', 'Partícula restrictiva que significa ''excepto'' o ''a menos que'', introduciendo una excepción a una declaración negativa precedente. Cinco de las ocho ocurrencias pertenecen aquí, todas en las narraciones cortesanas de Daniel: ''nadie puede mostrarlo excepto los dioses'' (Dn 2:11), ''no pudieron hallar motivo de acusación excepto en relación con su Dios'' (Dn 6:5). El árabe illa y el español ''excepto'' reflejan esta función restrictiva con precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108481, 'spa', 'Sino, sin embargo', 'Partícula adversativa que significa ''sino'' o ''sin embargo'', introduciendo un contraste sin negación previa. En Dn 2:30 pivota desde la negación (''no por sabiduría que haya en mí'') hacia el propósito (''sino para que la interpretación sea dada a conocer''). Esdras 5:12 la usa de manera similar: ''sino porque nuestros padres provocaron a Dios''. El español ''sino'' y ''pero'' capturan los matices correctivo y contrastivo respectivamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108483, 'spa', 'Por tanto', 'Partícula inferencial que significa ''por tanto'' o ''por esta razón'', extrayendo una conclusión lógica. Atestiguada únicamente en Dn 4:27, donde Daniel exhorta a Nabucodonosor: ''Por tanto, oh rey, acepta mi consejo''. El español ''por tanto'' y el alemán ''deshalb'' confirman la lectura causal-inferencial, una extensión pragmática natural del contraste adversativo a la consecuencia lógica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108485, 'spa', 'Partícula optativa que expresa deseo incumplido o anhelo', 'Partícula optativa que expresa deseo incumplido o anhelo: 14 apariciones, el sentido dominante. Abarca la oración de Abraham por Ismael (Gn 17:18), el deseo de muerte de los israelitas en el desierto (Nm 14:2) y el lamento de Moisés ''¡Oh, si fueran sabios!'' (Dt 32:29). El registro emocional va desde el anhelo desesperado hasta el pesar resignado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108486, 'spa', 'Partícula condicional que introduce una prótasis contrafáctica o hipotética', 'Partícula condicional que introduce una prótasis contrafáctica o hipotética: 7 apariciones. Expresa lo que habría ocurrido bajo condiciones que no se dieron: ''Si el SEÑOR hubiera querido matarnos, no habría aceptado nuestra ofrenda'' (Jue 13:23); ''Si mis hermanos vivieran, no os mataría'' (Jue 8:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108494, 'spa', 'Sentido negativo ''no''', 'Sentido negativo ''no'': una única aparición disputada en Job 9:33, donde לוּ podría funcionar como negación: ''no hay árbitro entre nosotros.'' Algunos gramáticos lo tratan como variante de לֹא (''no'') en vez de un sentido separado de לוּ. El contexto de Job, rico en partículas raras y arcaicas, puede conservar un uso semítico más antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108495, 'spa', 'Partícula dubitativa que expresa posibilidad', 'Partícula dubitativa que expresa posibilidad: una sola aparición en Gn 50:15, donde los hermanos de José temen ''quizá José nos aborrezca.'' El paso del deseo a la aprensión es sutil: la misma partícula que en otros lugares expresa anhelo aquí introduce una posibilidad angustiosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108496, 'spa', 'Aliados militares libios', 'Los libios aparecen como aliados militares en textos proféticos e históricos. Sisac invadió Judá con un ejército que incluía lubim junto a los suquienos y cusitas (2Cr 12:3). Asa enfrentó un vasto ejército etíope con lubim entre sus fuerzas (2Cr 16:8). Daniel profetiza que el rey del norte dominará a los lubim junto con Egipto y los cusitas (Dn 11:43). Nahúm recuerda a Nínive que incluso Tebas cayó pese a sus aliados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108497, 'spa', 'Pueblo etnico Lud', 'El nombre etnico y geografico Lud, que aparece en dos contextos genealogicos distintos. Como hijo de Sem (Gn 10:22 = 1 Cr 1:17), Lud se identifica tradicionalmente con Lidia en Asia Menor occidental, correspondiente al asirio Luddu. En los oraculos profeticos (Ez 27:10; 30:5; Is 66:19), Lud aparece entre pueblos guerreros africanos junto a Cus y Fut, probablemente un grupo distinto del Lud semitico. La coexistencia de ambos usos genera un desafio geografico permanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108498, 'spa', 'Lud/Ludim gentilicio', 'Lud hijo de Sem aparece en la Tabla de las Naciones (Gn 10:22 = 1Cr 1:17), representando a Lidia. Ludim hijo de Mizraim figura como descendiente africano (Gn 10:13 = 1Cr 1:11). Isaías sitúa a Lud en África con Tarsis y Put (Is 66:19), Ezequiel lo lista entre los mercenarios de Tiro (Ez 27:10) y aliados de Egipto (Ez 30:5). Los ''Ludim'' de Jeremías aparecen junto a Cus y Put como aliados de Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108499, 'spa', 'unirse a, adherirse', 'Sentido reflexivo del Nifal: unirse a, adherirse a, hacerse compañero de. Abarca las once apariciones en Nifal desde el Pentateuco hasta los Escritos. Génesis 29:34 ofrece la etimología fundacional: Lea nombra a su hijo Leví (לֵוִי) diciendo ''ahora mi esposo se unirá (yillaveh) a mí''. Números 18:2, 4 describe a los levitas uniéndose a Aarón para el servicio, jugando con la misma raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108507, 'spa', 'acompañar, escoltar', 'Sentido activo transitivo del Qal: acompañar o escoltar, presente únicamente en Eclesiastés 8:15 con sufijo pronominal (yilvennú, ''lo acompañará''). El Predicador elogia la alegría porque acompañará a la persona en sus afanes bajo el sol. Se diferencia del Nifal en la voz (activa frente a reflexiva) y la sintaxis (transitivo con objeto directo frente a unirse ''a'' con preposición).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108508, 'spa', 'Prestar — sentido causativo del Hifil', 'Prestar — sentido causativo del Hifil: prestar, conceder un préstamo a otra persona. Éxodo 22:25 establece la norma ética: prestar dinero al pobre sin cobrar interés. El Salmo 37:26 retrata al justo como quien siempre presta con generosidad (מַלְוֶה). Las traducciones al español como ''prestarás'' y al francés ''prêter'' captan esta provisión activa y generosa de recursos. La distinción entre prestar y tomar prestado se corresponde limpiamente con la alternancia de raíz hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108509, 'spa', 'Tomar prestado — sentido básico del Qal', 'Tomar prestado — sentido básico del Qal: tomar prestado, recibir un préstamo de otro. Proverbios 22:7 advierte que el que toma prestado (לֹוֶה) se convierte en siervo del prestamista, mientras que Isaías 24:2 usa el par ''como el prestamista, así el que toma prestado'' para describir la nivelación social en el juicio. El español ''toma prestado'' y el francés ''emprunter'' reflejan consistentemente este lado receptor de la transacción. Nehemías 5:4 registra al pueblo tomando préstamos bajo coacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108521, 'spa', 'Apartarse, ser perverso', 'Apartarse o ser torcido, donde el sentido literal de alejamiento se desliza hacia la perversidad moral. En Proverbios 3:21 y 4:21 (Qal/Hifil), significa simplemente «apartarse» de la vista. Pero el participio Nifal naloz lleva peso moral: el perverso de caminos tortuosos (Pr 2:15), la persona torcida que es abominación para Jehová (Pr 3:32) y la conducta desviada (Is 30:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108527, 'spa', 'Luz (ciudad cananea)', 'Topónimo cananeo de la ciudad posteriormente llamada Betel, y de un segundo asentamiento fundado por un refugiado de la original. Jacob llegó a Luz, encontró a Dios en un sueño y la renombró Betel (Gn 28:19; confirmado en 35:6 y 48:3). En las listas de límites tribales, Luz/Betel marca la frontera entre Efraín y Benjamín (Jos 16:2; 18:13). Jueces 1:23-26 relata cómo un hombre de Luz, perdonado durante la conquista israelita, fundó una nueva ciudad del mismo nombre en tierra hitita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108531, 'spa', 'tabla para escribir', 'tabla para escribir: una tabla plana para escritura, especialmente las tablas de piedra con el Decálogo. Domina el uso en Éxodo (24:12; 31:18; 32:15-16, 19; 34:1-4, 28-29) y Deuteronomio (4:13; 5:22; 9:9-17; 10:1-5). También se usa metafóricamente del corazón como superficie de escritura (Pr 3:3; 7:3; Jer 17:1) y de la tabla del profeta para exhibición pública (Is 30:8; Hab 2:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108534, 'spa', 'tablón o plancha', 'tablón o plancha: una tabla plana, tablón o placa usada en construcción o construcción naval. El altar se hace con tablas huecas (Éx 27:8; 38:7), las bases de Salomón tienen paneles grabados (1 R 7:36), la amada es comparada a una tabla de cedro (Cnt 8:9), y los barcos de Tiro se construyen con tablones dobles (Ez 27:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108542, 'spa', 'Topónimo moabita', 'Isaías 15:5 y Jeremías 48:5 comparten fraseología casi idéntica: «por la subida de Luhit» (מַעֲלֵה הַלּוּחִית/הַלֻּחִית) subirán llorando. La imagen de refugiados ascendiendo entre llanto refleja la huida desesperada de Moab. Jeremías presenta una variación ketiv-qeré, con diferencias escribales menores. El sitio se ubicaba al sur del río Arnón, aunque su localización exacta se desconoce.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108544, 'spa', 'Envolver o cubrir', 'En 1 Samuel 21:10 la espada de Goliat está «envuelta en un paño» (לוּטָה בַשִּׂמְלָה). En 1 Reyes 19:13 Elías «cubrió su rostro con su manto» (וַיָּלֶט פָּנָיו בְּאַדַּרְתּוֹ) al oír la voz apacible de Dios. Isaías 25:7 habla del «velo que cubre a todos los pueblos» (הַלּוֹט הַלּוֹט עַל־כָּל־הָעַמִּים), con un participio reduplicado que intensifica la imagen de ocultamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108546, 'spa', 'Lot (nombre propio)', 'Lot (nombre propio): nombre personal del sobrino de Abraham, cuyo arco narrativo en Génesis 11-19 transita del acompañamiento a la separación, el cautiverio, el rescate y la huida de la destrucción de Sodoma. Su elección de la llanura del Jordán (Gn 13:10-12), su rescate por Abraham (Gn 14:12-16) y su liberación de Sodoma (Gn 19:1-26) lo definen. Deuteronomio 2:9, 19 y el Salmo 83:9 hacen referencia a sus descendientes, los moabitas y amonitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108550, 'spa', 'Lotan (nombre propio)', 'Nombre propio de un jefe de clan horita, primogénito entre los hijos de Seir, registrado en la genealogía de los habitantes pre-israelitas de Edom (Gn 36:20, 22, 29; 1 Cr 1:38-39). Los hijos de Lotan fueron Hori y Hemam, y su hermana Timna llegó a ser ancestro de los amalecitas a través de Elifaz. La Septuaginta lo transcribe consistentemente como Λωταν.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108551, 'spa', 'Leví (patriarca y tribu)', 'Leví (patriarca y tribu): el nombre propio del tercer hijo de Jacob con Lea (Gn 29:34) y de la tribu descendiente de él, apartada para el servicio cultual. La etimología en Génesis conecta el nombre con la raíz לוה (''unirse''), expresando la esperanza de Lea de que su esposo finalmente se uniría a ella. Números 18:2–4 hace un juego de palabras sacerdotal con esta misma raíz. El español ''Leví'', el francés ''Lévi'' y el alemán ''Levi'' conservan el nombre de forma idéntica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108559, 'spa', 'Levitas en el templo', 'El término arameo aparece cuatro veces en la correspondencia oficial persa de Esdras. Los judíos, sacerdotes y levitas celebraron juntos la Pascua tras completar el templo (Esd 6:16). Los sacerdotes y levitas fueron organizados por divisiones para el servicio de Dios en Jerusalén (Esd 6:18). El decreto del rey Artajerjes permitía a cualquier sacerdote y levita que deseara regresar a Jerusalén hacerlo (Esd 7:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108561, 'spa', 'levitas (clase sacerdotal)', 'Miembros de la tribu de Leví en su función cúltica: los separados para el servicio en el tabernáculo y el templo, distintos de (aunque superpuestos con) el sacerdocio aarónico. Con 283 ocurrencias este es el uso estándar, que aparece desde Éx 6:25 hasta las listas postexílicas de Nehemías. Se emplea tanto como colectivo singular (hallēwî, ''el levita,'' Dt 18:6) como en plural (hallĕwiyyîm, ''los levitas,'' Nm 3:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108572, 'spa', 'Leví (nombre propio)', 'El patriarca Leví hijo de Jacob, o la tribu nombrada directamente en su honor más que como designación funcional. Solo 3 ocurrencias: Nm 26:58 (''las familias de Leví''), 1 Cr 23:27 (''las últimas palabras de David respecto a los hijos de Leví'') y 1 Cr 27:17 (un oficial ''para Leví''). Aquí la evidencia multilingüe pasa al tratamiento de nombre propio: español ''Leví,'' francés ''Lévi,'' alemán ''Levi.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108583, 'spa', 'Leviatán', 'Leviatán como criatura poderosa en contextos teofánicos y mitológicos: el monstruo del caos de múltiples cabezas aplastado por Dios (Sal 74:14), el dragón primordial cuyo despertar aterroriza la creación (Job 3:8), y la bestia que solo Dios puede someter (Job 41:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108584, 'spa', 'Serpiente huidiza', 'Leviatán como criatura marina en la alabanza creacional y la profecía escatológica: obra de Dios que «juega» en el océano (Sal 104:26, junto a navíos, sugiriendo una ballena) y la «serpiente tortuosa, la serpiente huidiza» de Isaías 27:1, a quien el Señor castigará con su gran espada en el día del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108588, 'spa', 'Si no, a menos que, de no haber sido (conjunción contrafactual) — Conjunción con', 'Si no, a menos que, de no haber sido (conjunción contrafactual) — Conjunción condicional contrafactual que significa ''si no, a menos que, de no ser que'', introduciendo situaciones hipotéticas contrarias a los hechos. Pasajes clave incluyen la advertencia de Jacob a Labán (Gn 31:42), el viaje demorado a Egipto (Gn 43:10), la burla de Sansón (Jue 14:18), la intervención de Abigail (1 S 25:34) y la aposiopesis del salmista que deja sin expresar la consecuencia terrible (Sal 27:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108594, 'spa', 'Alojarse por la noche en un lugar como viajero o huésped temporal', 'Alojarse por la noche en un lugar como viajero o huésped temporal: el sentido central de hospitalidad. Es la acepción más frecuente, presente en contextos narrativos de viaje y hospedaje. Pasajes clave incluyen la invitación de Lot a los ángeles (Gn 19:2) y la noche de Jacob en Bet-el (Gn 28:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108599, 'spa', 'De cosas inanimadas o cualidades abstractas que permanecen durante la noche o pe', 'De cosas inanimadas o cualidades abstractas que permanecen durante la noche o persisten hasta la mañana. Se aplica a la grasa sacrificial que no debe quedar hasta la mañana (Éx 23:18; 34:25), al salario que no debe pernoctar con el empleador (Lv 19:13) y al cuerpo colgado que debe ser sepultado antes del anochecer (Dt 21:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108600, 'spa', 'Morada extendida o figurada, que va más allá de una sola noche para indicar resi', 'Morada extendida o figurada, que va más allá de una sola noche para indicar residencia habitual o presencia duradera. En la literatura sapiencial y poética, el verbo describe el alma que mora en la prosperidad (Sal 25:13), el llanto que se aloja por la noche pero el gozo viene por la mañana (Sal 30:5), y el error que habita con una persona (Job 19:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108641, 'spa', 'murmurar, quejarse, refunfuñar — Murmurar, quejarse o refunfuñar, típicamente re', 'murmurar, quejarse, refunfuñar — Murmurar, quejarse o refunfuñar, típicamente referido a la comunidad israelita que expresa descontento contra Dios o sus líderes durante el período del desierto. Predominan las formas intransitivas Nifal y Hifil. Éxodo 15:24 registra la primera instancia tras las aguas amargas de Mara; Éxodo 16:2 y Números 16:11 continúan el patrón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108648, 'spa', 'pernoctar, pasar la noche — Pernoctar o pasar la noche, reflejando una raíz homó', 'pernoctar, pasar la noche — Pernoctar o pasar la noche, reflejando una raíz homónima separada que comparte la misma forma consonántica. En el Salmo 59:15, los enemigos del salmista rondan y pasan la noche, un uso que pertenece al verbo Qal común de alojamiento nocturno y no al vocabulario de murmuración del desierto. El contexto y la forma verbal son las claves para distinguir ambas raíces.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108649, 'spa', 'hacer murmurar — Sentido causativo Hifil que significa hacer que otros murmuren ', 'hacer murmurar — Sentido causativo Hifil que significa hacer que otros murmuren o incitar la queja. Números 14:36 aplica esto específicamente a los diez espías cuyo informe negativo hizo murmurar a toda la congregación. Es un desarrollo gramatical y semántico distinto de la murmuración intransitiva del sentido 1, atribuyendo la culpa a los instigadores en lugar de a la multitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108657, 'spa', 'Burlarse, mofarse o escarnecer con discurso despectivo, expresando desdén orgull', 'Burlarse, mofarse o escarnecer con discurso despectivo, expresando desdén orgulloso hacia la sabiduría, la corrección o la autoridad. El ''escarnecedor'' es un personaje arquetípico en Proverbios: incapaz de recibir disciplina (Pr 9:7-8), abominación para los demás (Pr 24:9), y contrastado con el sabio. Pasajes clave: Sal 1:1; Pr 3:34.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108660, 'spa', 'Servir como intérprete, mediador o enviado que transmite mensajes entre partes (', 'Servir como intérprete, mediador o enviado que transmite mensajes entre partes (participio Hifil en contextos diplomáticos o de abogacía). José usó un intérprete al hablar con sus hermanos (Gn 42:23), y Job imagina un mediador celestial que pudiera abogar ante Dios (Job 33:23). El puente semántico puede residir en la idea de hablar de manera indirecta, ya sea para ridiculizar o para traducir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108674, 'spa', 'Amasar masa', 'Trabajar harina y líquido a mano hasta formar masa para hornear. Aparece en relatos de hospitalidad: Sara amasando tortas para visitantes angélicos (Gn 18:6), la médium de Endor preparando pan para Saúl (1 Sam 28:24) y Tamar haciendo tortas ante Amnón (2 Sam 13:8). Oseas 7:4 lo emplea en metáfora del panadero y Jeremías 7:18 en denuncia de idolatría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108682, 'spa', 'Fresco, húmedo, verde', 'Describe algo que conserva su humedad natural, aplicado a vegetación, frutas y materiales. Varas frescas que Jacob peló (Gn 30:37); uvas frescas prohibidas al nazareo (Nm 6:3); cuerdas nuevas sin secar para atar a Sansón (Jue 16:7-8). La metáfora del árbol verde versus seco en Ezequiel (Ez 17:24; 21:3) contrasta con יָבֵשׁ (''seco'') para el juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108686, 'spa', 'mejilla (rasgo facial) — La mejilla como rasgo facial', 'mejilla (rasgo facial) — La mejilla como rasgo facial: el lado suave y visible del rostro, que aparece en contextos de belleza, insulto y expresión emocional. Golpear a alguien en la mejilla (1 R 22:24; 2 Cr 18:23) es un gesto de desprecio, mientras que Isaías 50:6 retrata al Siervo ofreciendo sus mejillas a quienes le arrancan la barba. Cantares 1:10 elogia hermosas mejillas adornadas con joyas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108687, 'spa', 'mandíbula, quijada — La mandíbula o quijada como hueso anatómico, especialmente ', 'mandíbula, quijada — La mandíbula o quijada como hueso anatómico, especialmente en el célebre episodio de Sansón con la quijada de asno (Jue 15:15-17). Oseas 11:4 retrata a Dios levantando el yugo de las mandíbulas de Israel como un labrador alivia la carga del buey, y Job 41:2 pregunta si se puede perforar la mandíbula de Leviatán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108689, 'spa', 'Lehi (topónimo) — El nombre propio de lugar Lehi (Jue 15', 'Lehi (topónimo) — El nombre propio de lugar Lehi (Jue 15:19), el sitio en Judá donde Sansón luchó contra los filisteos. El nombre deriva transparentemente de ''quijada'', conmemorando el arma y el campo de batalla. Dios abrió milagrosamente un manantial ''en Lehi'' para saciar la sed de Sansón tras su victoria, haciendo del topónimo también un memorial de la provisión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108703, 'spa', 'Topónimo en Judá', 'Jueces 15:9 relata que los filisteos acamparon «en Lehi» (בַּלֶּחִי), provocando el ataque de Sansón. El versículo 14 describe su llegada «a Lehi» (לֶחִי) cuando el Espíritu vino sobre él. El versículo 19 sitúa allí el manantial milagroso. La conexión del nombre con «quijada» (el arma que Sansón encontró) genera una narrativa etiológica que explica tanto el topónimo como el rasgo geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108704, 'spa', 'Lamer, devorar lamiendo', 'Lamer o devorar lamiendo, literal y figuradamente. Un buey lamiendo hierba como metáfora de Israel consumiendo Moab (Nm 22:4); fuego del cielo lamiendo el agua del altar de Elías (1 Re 18:38). «Lamer el polvo» (עָפָר) expresa humillación total: enemigos del rey mesiánico lamerán el polvo (Sal 72:9) y las naciones se arrastrarán como serpientes (Miq 7:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108709, 'spa', 'pelear, guerrear (Nifal)', 'El tronco Nifal (recíproco-reflexivo) que cubre la inmensa mayoría de las ocurrencias: pelear, entablar batalla, hacer la guerra contra un enemigo. La evidencia multilingüe —español pelear/luchar, francés combattre, alemán kämpfen— apunta uniformemente al conflicto militar organizado. Éx 17:8-10 narra la escena paradigmática: Amalec viene a pelear contra Israel y Josué es enviado a combatirlos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108735, 'spa', 'combatir; combatiente (Qal)', 'El raro tronco Qal, conservado solo en formas imperativas y participiales en los Salmos. En Sal 35:1, el salmista suplica לְחַם אֶת־לֹחֲמָי —''pelea contra los que me combaten''— donde el participio Qal funciona como sustantivo con el significado de ''combatiente, adversario.'' Sal 56:1-2 emplea igualmente el participio Qal para un oponente que acosa con su ataque.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108754, 'spa', 'Comer, consumir alimento', 'Usar como alimento, comer o consumir: alternativa poética de la tradición sapiencial frente al verbo cotidiano אָכַל. El verbo toma acusativo cognado directo (לֶחֶם, Pr 4:17; 23:6), partitivo con בְּ (Pr 9:5; Sal 141:4) o se usa absolutamente (Pr 23:1). El participio pasivo en Dt 32:24 extiende el sentido al consumo destructivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108760, 'spa', 'pan, hogaza', 'Pan literal, hogaza horneada de grano (279x). La acepción primaria y más frecuente, que abarca el pan cotidiano (Gn 3:19, ''con el sudor de tu rostro comerás pan''), el pan ceremonial (el pan de la Presencia), y el pan como gesto de hospitalidad (Gn 14:18, Melquisedec trae pan y vino). Las traducciones principales lo vierten de forma unánime: pan (español), pain (francés), Brot (alemán).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108767, 'spa', 'comida, sustento', 'Alimento o sustento en general, sin limitarse al pan horneado (19x). Cuando Levítico 3:11 denomina al sacrificio ''el alimento (léjem) de YHWH,'' o Números 28:24 habla del ''alimento de la ofrenda encendida,'' la palabra designa nutrición en sentido amplio. El cognado árabe laḥm (''carne'') conserva este significado alimentario más extenso. Traducciones como nourriture (francés) y Speise (alemán) reflejan esta extensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108784, 'spa', 'fruto, sustancia vital', 'Uso metafórico único en Jeremías 11:19 (1x): ''Destruyamos el árbol con su léjem,'' tradicionalmente vertido como ''con su pan'' o ''con su fruto.'' El profeta Jeremías es el árbol; su léjem es su vida, su sustancia productiva. El español ''con pan su'' preserva la forma literal, mientras que algunas tradiciones leen ''con su fruto.'' Es una metáfora profética donde el alimento representa la existencia misma del profeta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108812, 'spa', 'Concubinas reales', 'En Daniel 5:2 Belsasar ordena traer los vasos para que él, sus nobles, sus esposas y sus concubinas (וְלֶחֱנָתֵהּ) beban de ellos. El versículo 3 confirma el cumplimiento, y el 23 recapitula la ofensa mencionando a las concubinas (וְלֶחֱנָתָךְ) como partícipes del sacrilegio contra los vasos consagrados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108813, 'spa', 'oprimir, tratar con dureza — Oprimir, perseguir o tratar con dureza, ejerciendo ', 'oprimir, tratar con dureza — Oprimir, perseguir o tratar con dureza, ejerciendo poder injusto sobre personas vulnerables mediante presión social, económica o política. Este sentido dominante (15 apariciones) ancla la narrativa de liberación del Éxodo: ''He visto la opresión con que los egipcios los oprimen'' (Éx 3:9). Reaparece en la ley del pacto que prohíbe oprimir al extranjero (Éx 22:21; 23:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108814, 'spa', 'apretar, presionar físicamente — Apretar, presionar o acorralar físicamente, eje', 'apretar, presionar físicamente — Apretar, presionar o acorralar físicamente, ejerciendo fuerza corporal contra alguien o algo, empujándolo hacia un espacio estrecho. Tres apariciones preservan este sentido concreto y táctil: la burra de Balaam apretando su pie contra el muro (Nm 22:25), los amorreos empujando a los danitas hacia la serranía (Jue 1:34) y un oficial asediado siendo empujado con la puerta (2 R 6:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108822, 'spa', 'ser presionado, ser aplastado — Ser presionado o apretado pasivamente (Nifal), d', 'ser presionado, ser aplastado — Ser presionado o apretado pasivamente (Nifal), describiendo la experiencia de ser aplastado físicamente contra algo. Solo una aparición clara: la burra ''se apretó contra el muro'' en la narrativa de Balaam (Nm 22:25), donde la forma reflexivo-pasiva resalta la compresión involuntaria del animal en un espacio estrecho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108830, 'spa', 'opresión, angustia', 'La presión aplastante o angustia de la opresión, proveniente típicamente de enemigos extranjeros o señores despóticos. El uso fundacional es el reconocimiento divino de la opresión de Egipto sobre Israel (Éx 3:9), recordado en la confesión litúrgica (Dt 26:7). El ciclo de los jueces lo emplea repetidamente para la presión hostil que lleva a Israel a clamar por liberación (Jue 2:18; 4:3; 6:9; 10:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108839, 'spa', 'Susurrar y encantar', 'En 2 Samuel 12:19 David percibe que sus siervos «susurraban entre sí» (מִתְלַחֲשִׁים), deduciendo la muerte del niño. Salmo 41:7 describe a enemigos que «susurran contra mí» (יִתְלַחֲשׁוּ עָלַי), tramando el mal. Salmo 58:5 menciona «la voz de los encantadores» (קוֹל מְלַחֲשִׁים), expertos en murmurar conjuros a las serpientes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108840, 'spa', 'Encantamiento o hechizo', 'Encantamiento de serpientes o incantacion magica — un conjuro susurrado para controlar serpientes o ejercer poder oculto. Jer 8:17 advierte sobre serpientes que ningun לַחַשׁ puede encantar, y Ecl 10:11 observa que una serpiente que muerde antes de ser encantada hace inutil al encantador. Is 3:3 extiende esto a la pericia humana: el ''experto en encantamientos'' figura entre los pilares sociales de Jerusalen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108841, 'spa', 'Artes secretas, encantamientos', 'Artes secretas, encantamientos o misterios ocultos: las técnicas ocultas mediante las cuales los magos egipcios (חַרְטֻמִּים) replicaron o intentaron replicar las señales divinas obradas por Moisés. Las tres apariciones se concentran en la narrativa de las plagas de Éxodo: convirtieron agua en sangre ''con sus encantamientos'' (Éx 7:22), produjeron ranas (Éx 8:7), pero no pudieron producir piojos (Éx 8:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108842, 'spa', 'En secreto, a escondidas', 'En secreto, sigilosamente, a escondidas: el uso adverbial de בַּלָּט/בַּלַּאַט que describe una acción humana encubierta. Aparece en tres contextos narrativos donde alguien se aproxima o actúa sin ser detectado: Jael se acercó ''sigilosamente'' a Sísara con la estaca (Jue 4:21), Rut llegó ''en secreto'' y descubrió los pies de Booz en la era (Rut 3:7), y los siervos de Saúl hablaron ''en secreto'' a David (1 Sam 18:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108847, 'spa', 'Martillar, afilar, amolar', 'Martillar, afilar o amolar instrumentos metálicos, extendiéndose figuradamente a miradas hostiles. El participio Qal en Gn 4:22 identifica a Tubal-Caín como forjador arquetípico. En 1 S 13:20 describe el afilado de herramientas agrícolas. Sal 7:12 presenta a Dios afilando su espada, y Job 16:9 emplea ''aguzar los ojos'' como imagen de hostilidad penetrante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108848, 'spa', 'Guirnaldas ornamentales', 'En 1 Reyes 7:29, 30 y 36 se catalogan los elementos decorativos de las diez bases de bronce: leones, bueyes, querubines y «guirnaldas» (לֹיוֹת/וְלֹיוֹת) de obra labrada. El versículo 29 las asocia con leones y bueyes; el 30 con bordes y paneles; y el 36 con querubines, leones y palmeras grabados «con guirnaldas».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108849, 'spa', 'noche, período oscuro', 'El intervalo de oscuridad desde el ocaso hasta el amanecer, empleado como marcador temporal de sucesos, duraciones y ciclos recurrentes. Aparece en todos los géneros: ley (''aquella misma noche,'' Éx 12:42), narrativa (''de noche,'' Gn 14:15), sabiduría (''su lámpara no se apaga de noche,'' Pr 31:18) y lamento (''cada noche inundo mi lecho,'' Sal 6:7). Las 234 ocurrencias confirman su carácter universal en la Escritura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108863, 'spa', 'Noche, entidad cósmica', 'Ocurrencia singular en el relato de la creación donde Dios nombra la oscuridad ''Noche'' (Gn 1:5), tratándola no como mero período temporal sino como entidad cósmica designada. El español la escribe con mayúscula: Noche. El acto de nombramiento es paralelo al de llamar ''Día'' a la luz, estableciendo la dualidad fundamental del orden creado. Isaías 34:10 evoca este sentido cósmico con la noche perpetua como signo del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108874, 'spa', 'Noche, tiempo nocturno', 'Noche, tiempo nocturno: sustantivo temporal arameo exclusivo del libro de Daniel. Dn 2:19 usa la forma enfática לֵילְיָא para la noche de la revelación divina. Dn 5:30 marca la muerte de Belsasar ''en aquella noche''. Dn 7:2, 7 y 13 enmarcan las visiones apocalípticas como acontecidas ''en visiones de la noche''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108876, 'spa', 'León poético', 'Job 4:11 lamenta: «El león (לַיִשׁ) perece por falta de presa», en el discurso de Elifaz sobre la justicia divina. Proverbios 30:30 exalta al «león (לַיִשׁ), el más fuerte entre las bestias», que no retrocede ante nada. Isaías 30:6 menciona al «león (לַיִשׁ) y al cachorro» en el peligroso desierto del Néguev.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108878, 'spa', 'Ciudad cananea conquistada', 'Lais aparece cuatro veces en la narrativa de la conquista danita. Los espías danitas encontraron al «pueblo de Lais» viviendo con seguridad al estilo sidonio (Jue 18:7). Informaron sobre la tierra alrededor de Lais (Jue 18:14). Los danitas conquistaron y quemaron Lais (Jue 18:27) y reconstruyeron la ciudad llamándola Dan, «pero el nombre de la ciudad antes era Lais» (Jue 18:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108881, 'spa', 'capturar, tomar (Qal)', 'Capturar o asir por fuerza militar (Qal activo, 76x): la acepción primaria, que abarca la toma de ciudades, territorios y personas en guerra. Domina las narrativas de conquista: Josué tomando Hai (Jos 8:21), Caleb tomando Debir (Jue 1:12), David tomando Rabá (2 S 12:27-28). Se extiende a reyes que conquistan fortalezas y a generales que capturan prisioneros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108882, 'spa', 'ser capturado (Nifal)', 'Ser capturado, ser tomado (Nifal pasivo, 27x): la contraparte pasiva de la acepción 1, que describe ciudades y personas cayendo ante el enemigo. Es central en la narrativa de Acán, donde la suerte va estrechando progresivamente: la tribu es tomada, el clan es tomado, la familia es tomada (Jos 7:15-18; 1 S 10:20-21). También aparece en oráculos proféticos sobre ciudades que caerán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108898, 'spa', 'ser atrapado, enredado', 'Ser prendido, atrapado o enredado (Nifal, 9x): extensión figurada del pasivo donde el agente no es una fuerza militar sino una trampa, lazo o circunstancia. Los malvados quedan prendidos en sus propios ardides (Sal 9:15; Pr 11:6), una persona es atrapada por palabras precipitadas (Pr 6:2), y Qohélet advierte que los mortales son como peces atrapados en la red (Ec 9:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108905, 'spa', 'congelarse, cuajarse', 'Congelarse, solidificarse (Hitpael/forma inusual, 1x): en Job 38:30, la superficie del abismo ''se congela,'' el agua asiéndose a sí misma hasta convertirse en hielo. El cognado árabe lakida (''pegarse, adherirse'') ilumina este uso: el sentido es adhesión física, lo líquido volviéndose sólido. Una extensión semántica única desde ''asir'' hacia la cohesión material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108909, 'spa', 'atrapar, cazar (Qal)', 'Atrapar o cazar activamente (Qal, 7x): la acepción del cazador o trampero, que implica tender un lazo, capturar un animal o atrapar a alguien con astucia. Sansón atrapa trescientas zorras (Jue 15:4), Dios atrapa a los sabios en su propia astucia (Job 5:13, citado por Pablo en 1 Co 3:19), y Amós pregunta retóricamente si un ave cae sin trampa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108943, 'spa', 'trabarse, ensamblarse', 'Sujetarse firmemente, trabarse (Hitpael, 1x): en Job 41:17, describiendo las escamas del Leviatán, las placas de armadura ''se agarran'' unas a otras, trabadas e inseparables. Como la acepción 5, este uso se apoya en el significado adhesivo de la raíz visible en el árabe lakida. Describe vinculación física mutua, no captura bélica: las dos apariciones en Job revelan un estrato semántico arcaico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108951, 'spa', 'Una importante ciudad fortificada en la Sefelá al suroeste de Jerusalén (actual ', 'Una importante ciudad fortificada en la Sefelá al suroeste de Jerusalén (actual Tell ed-Duweir). Conquistada por Josué a su rey amorreo (Jos 10:3-35), fortificada por Roboam (2 Cr 11:9), y sitiada por Senaquerib (2 Re 18:14, 17) y Nabucodonosor (Jer 34:7). Miqueas la acusó de ser ''el principio de pecado para la hija de Sion'' (Mi 1:13). Las Cartas de Laquis atestiguan los últimos días antes de la conquista babilónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108958, 'spa', 'Lazos (sujetadores textiles) — Lazos (לֻלָאֹת), los sujetadores textiles unidos ', 'Lazos (sujetadores textiles) — Lazos (לֻלָאֹת), los sujetadores textiles unidos a los bordes de los paneles de las cortinas del tabernáculo. Término exclusivamente sacerdotal de construcción; sus trece apariciones se encuentran en las instrucciones y la ejecución del tabernáculo (Éx 26:4–5, 10–11; 36:11–12, 17). Conjuntos de cincuenta lazos en cada borde de cortina se alinean con los lazos correspondientes del panel adyacente, recibiendo corchetes de oro o bronce para unir las secciones en una sola estructura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108961, 'spa', 'El sentido Piel dominante', 'El sentido Piel dominante: enseñar, instruir o adiestrar activamente a alguien. Es la contraparte causativa del Qal, el lado del maestro en la relación de aprendizaje. Especialmente prominente en Deuteronomio, donde se ordena a Moisés enseñar a Israel los estatutos de Dios (Dt 4:1, 4:10, 4:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108963, 'spa', 'El sentido Qal básico', 'El sentido Qal básico: aprender, estudiar o habituarse. Abarca tanto el aprendizaje positivo — estudiar los mandamientos de Dios para temer al SEÑOR (Dt 14:23, 17:19) — como el aprendizaje negativo, como adoptar las prácticas abominables de las naciones (Dt 18:9, Sal 106:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108973, 'spa', 'El participio Piel sustantivado que funciona como nombre', 'El participio Piel sustantivado que funciona como nombre: ''maestro, instructor''. Se distingue del sentido verbal activo por su sintaxis nominal: lleva artículo y sufijos posesivos (מְלַמְּדַי, ''mis maestros'', Pr 5:13; Sal 119:99). El Salmo 94:10 pregunta retóricamente: ''El que enseña al hombre el saber, ¿no habrá de reprender?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (108989, 'spa', 'Las formas pasivas (Pual y participio pasivo Qal)', 'Las formas pasivas (Pual y participio pasivo Qal): adiestrado, disciplinado, acostumbrado. Se usa para guerreros ''entrenados para la guerra'' que portan escudo y espada (1 Cr 5:18), músicos expertos (1 Cr 25:7) y la escolta armada de Salomón ''diestra en la guerra'' (Cnt 3:8). Jeremías 31:18 usa la imagen de un becerro indómito que necesita ser disciplinado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109024, 'spa', 'A, para, sobre (poético)', 'Preposición poética arcaica que funciona de manera idéntica a לְ (''a, para, sobre''), pero restringida al verso elevado. El elemento מוֹ posiblemente deriva de una partícula enclítica antigua, otorgando a la forma un carácter solemne y arcaizante. Job la emplea repetidamente (27:14; 29:21; 38:40; 40:4), y también aparece en la bendición ancestral de Gn 9:26-27.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109028, 'spa', 'Enseñado; discípulo', 'Quien ha sido enseñado, instruido o acostumbrado a algo, usado tanto como adjetivo verdadero como sustantivo con el sentido de ''discípulo, alumno''. En Isaías, el término designa a quienes reciben instrucción divina: el profeta sella el testimonio ''entre mis discípulos'' (Is 8:16), y el Siervo posee la ''lengua de los instruidos'' (Is 50:4), imagen de un hablar receptivo capacitado por el Espíritu. En Jeremías describe hábito arraigado: una asna ''acostumbrada'' al desierto (Jer 2:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109034, 'spa', 'Lamec', 'El Lamec cainita, descendiente de Caín en la séptima generación desde Adán. Destaca como el primer polígamo (casado con Ada y Zila) y autor del ''Canto de la Espada'' (Gn 4:23-24), jactancia de violencia desmesurada. Padre de Jabal, Jubal y Tubal-Caín, fundadores de las artes pastoril, musical y metalúrgica (Gn 4:18-22). Su figura encarna la escalada de violencia en la línea de Caín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109039, 'spa', 'burlarse, escarnecer, ridiculizar — Burlarse, escarnecer o tratar con desprecio ', 'burlarse, escarnecer, ridiculizar — Burlarse, escarnecer o tratar con desprecio abierto (Qal y Hifil). Usado para el triunfo de Jerusalén sobre Senaquerib (2 R 19:21 = Is 37:22), para Dios ridiculizando a los malvados (Sal 2:4; Job 9:23), para enemigos burlándose del justo (Jer 20:7; Neh 2:19) y para la Sabiduría personificada burlándose de los complacientes (Pr 1:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109051, 'spa', 'balbucear, hablar ininteligiblemente — Balbucear o hablar de manera ininteligibl', 'balbucear, hablar ininteligiblemente — Balbucear o hablar de manera ininteligible (Nifal), refiriéndose a un habla extranjera o incomprensible. Se encuentra solo en Isaías 33:19, describiendo a un pueblo feroz cuya lengua Israel no puede entender — ''un pueblo de labio balbuciente''. El cognado siríaco significa ''tartamudear'' y el paralelo árabe لجلج igualmente denota habla confusa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109057, 'spa', 'Burla, escarnio, mofa', 'Burla, escarnio o mofa — ridículo despectivo sufrido por individuos o por la nación, a menudo emparejado con oprobio (herpah) y befa (qeles) en los lamentos comunitarios (Sal 44:13; 79:4; 123:4). Elihú acusa a Job de tratar el habla blasfema con indiferencia casual, «bebiendo escarnio como agua» (Job 34:7), mientras que Ezequiel lo incluye en la copa de juicio derramada sobre Jerusalén (Ez 23:32; 36:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109065, 'spa', 'Laadán (nombre propio)', 'El nombre propio Laadán, que identifica a dos figuras del Antiguo Testamento: (a) un efrateo en la línea ancestral de Josué (1 Cr 7:26), y (b) un levita gersonita cuyos descendientes sirvieron como tesoreros del templo bajo la reorganización de David (1 Cr 23:7-9; 26:21). La diversidad en la LXX (Laadán, Edán, Ladán) evidencia cierta fluidez en la transmisión del nombre en la tradición griega.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109070, 'spa', 'Ajenjo (planta amarga)', 'La hierba amarga ajenjo (Artemisia), usada metafóricamente para las consecuencias ponzoñosas del pecado, la injusticia y el juicio divino. En el discurso profético, Dios declara que alimentará a su pueblo con ajenjo y le dará agua envenenada (Jer 9:15; 23:15), mientras Lamentaciones 3:15 y 3:19 lo emplean como lamento personal por la aflicción. Amós 5:7 y 6:12 empareja ajenjo con la perversión de la justicia, y Proverbios 5:4 lo convierte en imagen de la seducción mortal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109074, 'spa', 'Antorcha, tea — Una antorcha o tea encendida, en sentido literal y figurado', 'Antorcha, tea — Una antorcha o tea encendida, en sentido literal y figurado. Aparece en la teofanía del pacto abrahámico como ''antorcha de fuego'' entre las piezas (Gn 15:17), en el ataque nocturno de Gedeón (Jue 7:16, 20) y en la destrucción de los campos filisteos por Sansón (Jue 15:4–5). Se extiende a los relámpagos en el Sinaí (Éx 20:18), los ojos angélicos (Dn 10:6), los carros centelleantes (Nah 2:5) y los líderes conquistadores de Judá (Zac 12:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109088, 'spa', 'Torcer y agarrar', 'Jueces 16:29 describe el acto final de Sansón: «y agarró (וַיִּלְפֹּת) las dos columnas centrales», usando fuerza y palanca para derribar el templo. Rut 3:8 relata la sorpresa nocturna de Booz: «el hombre se volvió bruscamente (וַיִּלָּפֵת) y he aquí, ¡una mujer!». Job 6:18 describe senderos que «se tuercen» (יִלָּפְתוּ) y se pierden.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109089, 'spa', 'Escarnio y burla', 'La evidencia multilingüe apunta de manera consistente al habla y la actitud de mofa despectiva. En Proverbios describe a los burladores habituales (1:22; 29:8), mientras que Isaías 28:14 condena a los líderes burlones de Jerusalén que confían en mentiras en vez de aferrarse al pacto de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109092, 'spa', 'tomar, asir (Qal)', 'Sentido transitivo central del Qal: tomar, asir, agarrar, recoger. Con mucho el uso más frecuente, abarca la aprehensión física, la selección, la captura y la adquisición. Desde ''Dios tomó al hombre'' (Gn 2:15) hasta ''toma a tu hijo'' (Gn 22:2), el verbo expresa apropiación activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109146, 'spa', 'recibir, aceptar (Qal)', 'Recibir o aceptar lo que es ofrecido o dado, distinguiéndose de la aprehensión activa por la transferencia voluntaria desde otra parte. Se observa en contextos sacerdotales como recibir diezmos (Nm 18:26) y en pasajes como ''la tierra abrió su boca para recibir'' (Gn 4:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109147, 'spa', 'ser tomado (Nifal/pasivo)', 'Pasiva: ser tomado, capturado, llevado por otro agente. Las formas del Nifal y del Qal pasivo aparecen en relatos de mujeres tomadas (Gn 12:15), ciudades capturadas y personas llevadas cautivas. La distinción de raíz verbal marca claramente la voz pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109157, 'spa', 'centellear, flamear (Hitpael)', 'Sentido raro del Hitpael: centellear o flamear de un lado a otro. Usado del fuego ''centelleando continuamente'' en Éx 9:24 y de la apariencia ígnea en Ez 1:4. Extensión reflexivo-iterativa que salta semánticamente desde ''tomar turnos'' hacia la imagen del fuego parpadeante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109163, 'spa', 'quitar, arrebatar', 'Quitar o retirar algo a alguien — el matiz ablativo de לָקַח donde lo tomado es despojado o sustraído. En Éx 21:10, un esposo no debe disminuir los derechos de su esposa; en Os 4:11, el vino y el mosto ''quitan'' el entendimiento. Sentido de desposesión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109178, 'spa', 'traer, ir a buscar (Qal)', 'Ir a buscar, traer, ir y conseguir, enfatizando el movimiento hacia el hablante. Abraham dice ''déjenme traer un bocado de pan'' (Gn 18:5); Rebeca ordena a Jacob ''ve y tráeme dos cabritos'' (Gn 27:9). Este sentido incorpora un componente direccional ausente en el simple ''tomar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109219, 'spa', 'Enseñanza, instrucción, aprendizaje', 'Sentido central de enseñanza o aprendizaje: conocimiento recibido y asimilado. Subjetivamente, es lo que acumula el sabio (Pr 1:5; 9:9). Objetivamente, es el contenido transmitido: la enseñanza de Moisés cae como lluvia (Dt 32:2) y Job afirma ''mi doctrina es pura'' (Job 11:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109221, 'spa', 'Persuasión, elocuencia seductora', 'Sentido especializado de poder persuasivo o elocuencia seductora, atestiguado en Proverbios 7:21 donde la mujer extraña vence a su víctima ''con su persuasión'' (liqqachah). Aquí leqach ya no es instrucción neutra sino la fuerza cautivadora de palabras irresistibles, lo que Proverbios 16:21 llama la ''persuasión'' que la dulzura de labios acrecienta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109224, 'spa', 'Recoger, juntar (Qal)', 'Recoger, juntar (Qal): Acción básica de recoger o juntar objetos del suelo en el tallo Qal. Domina los relatos del maná (Éx 16:4-22), donde cada israelita recoge el pan diario del cielo. También se usa para juntar piedras en un montón durante el pacto de Labán con Jacob (Gn 31:46) y para recoger lirios (Cnt 6:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109226, 'spa', 'Espigar, recoger a fondo (Piel)', 'Espigar, recoger a fondo (Piel): Espigueo intensivo en el tallo Piel, que describe la recolección deliberada y exhaustiva de grano sobrante en los campos cosechados. Es el sentido detrás de las leyes de espigueo de Levítico 19:9-10 y 23:22, donde las esquinas y el grano caído deben dejarse para el pobre. El espigueo de Rut en el campo de Booz (Rut 2) encarna esta práctica por excelencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109233, 'spa', 'Reunirse, congregarse (Hitpael)', 'Reunirse, congregarse (Hitpael): Uso raro en Hitpael (reflexivo-recíproco) en Jueces 11:3, donde hombres vanos ''se reunieron'' en torno a Jefté. El tallo reflexivo cambia el significado de recolectar objetos a personas que se congregan por voluntad propia, indicando una acción comunitaria autodirigida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109240, 'spa', 'Ser recogido (Pual)', 'Ser recogido (Pual): Pasivo Pual en Isaías 27:12, donde Israel ''será recogido'' uno por uno — Dios actuando como cosechador, recogiendo individuos exiliados como un espigador recoge grano caído. La voz pasiva enfatiza al agente divino que realiza la recolección, no el esfuerzo humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109251, 'spa', 'Lamer agua (con la lengua)', 'Lamer agua con la lengua, describiendo cómo una persona o animal bebe recogiendo el agua con la boca. Central en la narrativa de Gedeón (Jue 7:5-7), donde los soldados son probados: «a todo el que lama las aguas con su lengua como lame el perro, lo pondrás aparte». La forma participial Piel hamlaqqeqim («los que lamen») en Jue 7:6 designa a los trescientos selectos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109254, 'spa', 'Lamer una superficie', 'Lamer una superficie — específicamente perros lamiendo sangre del suelo o de un estanque. En 1 R 21:19 Elías profetiza: «En el mismo lugar donde los perros lamieron la sangre de Nabot, los perros lamerán también tu sangre», y 1 R 22:38 registra su cumplimiento cuando los perros lamieron la sangre de Acab en el estanque de Samaria. El objeto directo es una sustancia sobre una superficie (sangre, polvo) y no un cuerpo de agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109259, 'spa', 'lengua, órgano del habla', 'El órgano literal de la boca, extendido figuradamente como instrumento del habla: alabanza, oración, calumnia y astucia operan a través de él. Éxodo 4:10 registra la protesta de Moisés de ser ''pesado de lengua,'' mientras 2 Samuel 23:2 coloca la palabra de Dios sobre la lengua de David. El árabe لِسَان y el etíope ልሳን comparten este significado primario en todo el semítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109266, 'spa', 'idioma, lengua de un pueblo', 'Por metonimia, la lengua designa el idioma que habla un pueblo. Aparece característicamente en la Tabla de las Naciones (Gn 10:5, 20, 31) y en el decreto de Ester enviado a cada provincia ''conforme a su lengua'' (Est 1:22). El español lengua, el francés langue y el alemán Zunge conservan todos este mismo desplazamiento del órgano al idioma, confirmando un camino cognitivo prácticamente universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109278, 'spa', 'bahía, lengua de mar', 'Accidente geográfico en forma de lengua, específicamente una bahía o ensenada. Las tres ocurrencias aparecen en descripciones de límites en Josué (15:2, 15:5, 18:19), referidas a la lengua meridional del mar Muerto. Se trata de un término topográfico diferenciado del sentido corporal, donde la forma del accidente costero motiva la metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109283, 'spa', 'barra, lingote en forma de lengua', 'Objeto sólido en forma de lengua, específicamente una barra o lingote de metal precioso. Ambas ocurrencias describen la ''lengua de oro'' que Acán tomó de Jericó (Jos 7:21, 24). La metáfora de forma es transparente: la pieza de oro fundido adopta la silueta alargada de una lengua, y el hebreo la nombra según esa semejanza visual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109303, 'spa', 'Cámara, sala o aposento dentro de un templo, palacio o complejo de edificio públ', 'Cámara, sala o aposento dentro de un templo, palacio o complejo de edificio público, con funciones diversas: comida sacrificial (1 S 9:22), encuentro profético (Jer 35:2-4; 36:10), almacenamiento de diezmos y ofrendas (Neh 10:37-39; 13:4-9) y aposentos sacerdotales (Ez 40:17; 42:1-13; 1 Cr 9:26, 33). La especificidad arquitectónica varía desde una única sala de banquete en las narraciones tempranas hasta suites completas de habitaciones en la visión de Ezequiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109323, 'spa', 'Calumnia y difamación', 'La evidencia interlingüística señala uniformemente al habla calumniosa: acusaciones falsas y malintencionadas. El Salmo 101:5 presenta al calumniador secreto como intolerable ante la presencia de Dios, mientras que Proverbios 30:10 advierte contra calumniar incluso a un siervo, para que el acusador no sea hallado culpable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109324, 'spa', 'Lengua / idioma (arameo)', 'Lengua en el sentido de idioma hablado o grupo linguistico, presente en la formula fija aramea ''pueblos, naciones y lenguas'' (Dan 3:4, 7, 29; 4:1; 5:19; 6:25; 7:14). En sus atestiguaciones biblicas nunca se refiere al organo fisico; siempre designa una comunidad linguistica. El cognado siriaco confirma este campo semantico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109330, 'spa', 'muy, en gran manera', 'Variante adverbial que intensifica grado en contextos donde el sentido 1 y este se solapan. Cubre pasajes como Génesis 1:31 (''muy bueno''), Génesis 4:5 (''sumamente airado'') y Génesis 7:18-19 (''crecieron las aguas en gran manera''). El uso nominal ocasional de Deuteronomio 6:5 (''con todo tu מְאֹד'') extiende la raíz al ámbito de la fuerza o capacidad máxima, mostrando la flexibilidad semántica de esta partícula.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109336, 'spa', 'numeral cardinal cien', 'El numeral cardinal ''cien'' en todas sus formas flexionadas — singular, dual (''doscientos'') y plural (''cientos'') — empleado para contar personas, años, medidas y cantidades monetarias. Es el sentido cuantitativo básico que cubre edades (Gn 5:4-32), dimensiones (Éx 27:9-18), censos militares (Nm 31:32-46) y pagos de tributo. El español ''cientos,'' el francés ''cent'' y el alemán ''hundert'' lo traducen de manera uniforme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109341, 'spa', 'unidad militar de cientos', 'El plural ''cientos'' (הַמֵּאוֹת) funcionando como designación de divisiones militares o administrativas — compañías de aproximadamente cien hombres. Aparece típicamente con artículo en la fórmula ''jefes/oficiales de cientos'' (שָׂרֵי מֵאוֹת, Éx 18:21, 25; Nm 31:14, 48). Las glosas multilingües suelen incluir el artículo (''los cientos,'' ''las centenas''), confirmando que se trata de una unidad organizativa reconocida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109350, 'spa', 'centésima parte (fracción)', 'Sentido fraccionario: ''la centésima parte de,'' que aparece en Nehemías 5:11 donde Nehemías exige a los acreedores devolver la centésima (מְאַת) del dinero, grano, vino y aceite que habían estado cobrando. Las glosas multilingües muestran todas una construcción partitiva (''y la centésima de''), distinguiendo este raro uso proporcional del numeral cardinal ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109358, 'spa', 'Cien (numeral cardinal)', 'El número cardinal cien, empleado en enumeraciones de animales sacrificiales, bienes y unidades administrativas. En Esdras 6:17, las ofrendas de dedicación se cuentan como cien toros, doscientos carneros, cuatrocientos corderos y doce machos cabríos; en Esdras 7:22 Artajerjes especifica hasta cien talentos de plata, cien coros de trigo, cien batos de vino y cien batos de aceite.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109363, 'spa', 'defecto, mancha, imperfección — Un defecto, mancha o imperfección física que hac', 'defecto, mancha, imperfección — Un defecto, mancha o imperfección física que hace a una persona o animal ritualmente inapto. Usado principalmente en la legislación sacerdotal y de santidad para descalificar a sacerdotes con defectos de acercarse al altar (Lv 21:17-23) y a animales imperfectos del sacrificio (Lv 22:20-25; Nm 19:2; Dt 15:21). También describe la ausencia de defecto como belleza ideal (2 S 14:25; Cnt 4:7) y se extiende metafóricamente a la mancha moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109368, 'spa', 'Algo, alguna cosa', 'Algo, alguna cosa: Pronombre indefinido usado abrumadoramente en cláusulas negativas con el sentido de ''nada en absoluto, ni una cosa''. A Abraham se le dice que no haga מְאוּמָה a Isaac (Gn 22:12), Jacob rehúsa מְאוּמָה de Labán (Gn 30:31) y Samuel afirma no haber tomado מְאוּמָה de nadie (1 S 12:4-5). También aparece en negaciones eufemísticas referidas a delitos (Gn 40:15). Sus cognados asirios mamman/mimma confirman el alcance indefinido generalizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109375, 'spa', 'luz, luminaria (singular/general) — Una fuente de luz o luminaria en sentido sin', 'luz, luminaria (singular/general) — Una fuente de luz o luminaria en sentido singular o general, abarcando el sol, la luna, el candelabro sagrado y el resplandor figurado. La mayoría de las apariciones caen aquí, incluyendo la ''luminaria mayor'' y la ''luminaria menor'' de Gn 1:16, la menorá descrita como מְנֹרַת הַמָּאוֹר (''el candelabro de la luz'') en Éx 35:14 y la metafórica ''luz de los ojos'' en Pr 15:30.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109378, 'spa', 'luminarias, luces (plural/cuerpos celestes) — La forma plural מְאֹרֹת / מְאוֹרֹת', 'luminarias, luces (plural/cuerpos celestes) — La forma plural מְאֹרֹת / מְאוֹרֹת que designa las luminarias celestes como clase — sol, luna y estrellas como portadores de luz creados y puestos en el firmamento. Este sentido se concentra en Génesis 1:14-16, donde Dios dice ''haya luminarias en la expansión'', y en Ezequiel 32:8 donde el juicio oscurece ''todas las luminarias de luz en los cielos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109385, 'spa', 'Balanzas para pesar — Un par de balanzas o platillos (siempre en dual', 'Balanzas para pesar — Un par de balanzas o platillos (siempre en dual: מֹאזְנַיִם) usados como instrumento para pesar bienes, dinero o mercancías en el comercio. Empleado literalmente en Jeremías 32:10 para pesar plata y en Ezequiel 5:1 para pesar cabello. Extendido figuradamente a la evaluación divina y moral: ''balanzas justas'' (מֹאזְנֵי צֶדֶק) en Levítico 19:36 y Ezequiel 45:10 representan la rectitud económica, mientras que ''balanzas de engaño'' en Proverbios 11:1 denuncian la deshonestidad comercial. Isaías coloca las islas en las balanzas de Dios como mero polvo (40:12, 15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109396, 'spa', 'Sustancia comestible o alimento en el sentido más amplio, abarcando productos cr', 'Sustancia comestible o alimento en el sentido más amplio, abarcando productos crudos, comidas preparadas y provisiones. Aparece por primera vez describiendo los árboles del Edén como ''buenos para comer'' (Gn 2:9; 3:6), luego las provisiones del arca de Noé (Gn 6:21), los árboles frutales en los códigos legales (Lv 19:23; Dt 20:20), y el alimento real (1 Re 10:5). Habacuc lo extiende figuradamente a los pueblos conquistados devorados como peces (Hab 1:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109412, 'spa', 'Cuchillo sacrificial', 'El cuchillo aparece en relatos de sacrificio y violencia. Abraham «tomó el cuchillo para inmolar a su hijo» en obediencia a la prueba de Dios (Gn 22:6, 10). El levita en Jueces «tomó un cuchillo y agarró a su concubina y la dividió en doce partes» (Jue 19:29), provocando la indignación que condujo a una guerra civil. Proverbios advierte sobre una generación «cuyos dientes son cuchillos» para devorar al afligido (Pr 30:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109415, 'spa', 'Decreto o mandato real', 'Las traducciones reflejan consistentemente un mandato, decreto o palabra con connotaciones de autoridad real. Las tres ocurrencias en Ester se refieren a directivas autoritativas: la negativa de Vasti a obedecer la orden del rey, la fiel observancia de Ester de la palabra de Mardoqueo y el decreto escrito concerniente a Purim.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109417, 'spa', 'Vasos o utensilios sagrados', 'Vasos o utensilios sagrados del templo de Jerusalen, presentes en las secciones arameas de Esdras y Daniel. En Esdras 5:14-15 y 6:5, el termino designa los implementos de oro y plata inventariados para su devolucion bajo el decreto persa; en Daniel 5:2-3, 23, son los vasos santos profanados en el banquete de Belsasar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109421, 'spa', 'Rehusar, negarse', 'Rehusar, negarse: Rehusar o declinar con intención deliberada, expresando renuencia voluntaria y no mera incapacidad. El término abarca un espectro moral: desde el rechazo justo (José rechazando el adulterio, Gn 39:8; el varón de Dios rechazando la recompensa, 1 R 20:35) hasta la obstinación culpable (Faraón negándose a dejar ir a Israel, Éx 7:14; 9:2; 10:3-4; Israel negándose a arrepentirse, Jer 5:3; 8:5). Típicamente va seguido de un infinitivo complementario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109444, 'spa', 'Negativa obstinada', 'El participio aparece cuatro veces describiendo una negativa tenaz a obedecer a Dios. Faraón es designado tres veces como «el que rehúsa dejar ir al pueblo» antes de plagas sucesivas: las ranas (Éx 8:2), la peste del ganado (Éx 9:2) y las langostas (Éx 10:4). A Sedequías se le advierte: «Si tú rehúsas rendirte» ante los babilonios, sobrevendrá el desastre (Jer 38:21). En cada caso, la construcción hebrea es «rehusando» seguida de infinitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109446, 'spa', 'El sentido Qal principal', 'El sentido Qal principal: rechazar, rehusar o repudiar a una persona, cosa o mandamiento divino. Abarca las grandes crisis del pacto: Israel rechazando la realeza de Dios (1 S 8:7), Dios desechando a Saúl (1 S 15:23, 26), Israel despreciando la Torá (Lv 26:43-44), y el pueblo rehusando las aguas apacibles de Siloé (Is 8:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109451, 'spa', 'Despreciar, desdeñar o tratar con menosprecio — se distingue del rechazo directo', 'Despreciar, desdeñar o tratar con menosprecio — se distingue del rechazo directo por una actitud de desdén más que de negación formal. El malvado ''desprecia'' la corrección (Job 5:17), el arrogante ''no aborrece el mal'' porque ''desprecia'' la sabiduría (Sal 36:1-4). El matiz es de desdén altivo más que de repudio categórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109476, 'spa', 'El significado Nifal pasivo o estativo', 'El significado Nifal pasivo o estativo: ser rechazado, desechado o considerado reprobado. Tres casos claros llevan morfología pasiva: el reprobado cuya conducta lo marca como rechazado ante los ojos del justo (Sal 15:4), la esposa ''repudiada'' y luego convocada de nuevo por Dios (Is 54:6), e Israel como ''plata desechada'' que no pasa la prueba del refinador (Jer 6:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109494, 'spa', 'Un sentido singular intensificado que significa aborrecer, detestar o encontrar ', 'Un sentido singular intensificado que significa aborrecer, detestar o encontrar la propia existencia insoportable. Job 7:16 se yergue solo: ''Aborrezco mi vida; no viviré para siempre'' — donde el rechazo se vuelve repulsión visceral dirigida contra uno mismo. El objeto no es otra persona ni la ley de Dios, sino la propia vida del que sufre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109501, 'spa', 'Aflicción punzante', 'El participio aparece en textos proféticos y sacerdotales sobre la aflicción dolorosa. Ezequiel promete que los vecinos hostiles ya no serán «zarza punzante» para Israel (Ez 28:24, en paralelo con «espina dolorosa»). Las regulaciones sacerdotales sobre la lepra describen tres veces la lepra «maligna» en vestiduras o casas: cuando la enfermedad resulta ser «maligna» tras la inspección, el objeto infectado debe ser quemado (Lv 13:51-52; 14:44).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109502, 'spa', 'Emboscada, celada', 'Emboscada o lugar de acecho, y por metonimia las tropas ocultas, en contextos militares y figurados. Jos 8:9 designa la celada contra Hai; Jue 9:35 describe a Gaal divisando las fuerzas de Abimelec. En 2 Cr 13:13 Jeroboam envía una doble emboscada contra Judá. Sal 10:8 lo aplica al impío que acecha al pobre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109503, 'spa', 'Maldición divina pactual', 'Una maldición divina o autoritativa que acarrea ruina material y espiritual. Las cinco apariciones apuntan a consecuencias del pacto: Deuteronomio 28:20 la vincula a la desobediencia, Malaquías 2:2 y 3:9 a la infidelidad sacerdotal y comunitaria, y Proverbios al carácter moral. Las traducciones en diversas lenguas la rinden uniformemente como una imprecación solemne, no como un insulto casual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109505, 'spa', 'La puesta o el ocaso del sol, y por extensión la dirección oeste', 'La puesta o el ocaso del sol, y por extensión la dirección oeste. El Salmo 50:1 empareja ''desde la salida del sol hasta su ocaso'' como un merismo que abarca toda la tierra. ''Puesta de'' en español resalta el sentido astral que ''entrance of'' en inglés puede oscurecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109506, 'spa', 'La entrada física o puerta de acceso a un espacio definido', 'La entrada física o puerta de acceso a un espacio definido: una puerta de ciudad (Jue 1:24-25), un umbral del templo (2 R 16:18) o un pasaje de guardia (1 Cr 9:19). Las traducciones al español con ''entrada de'' reflejan consistentemente este sentido espacial y arquitectónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109511, 'spa', 'El acto o evento de entrar, usado como sustantivo verbal', 'El acto o evento de entrar, usado como sustantivo verbal. En 2 Samuel 3:25 se escudriña el ''entrar y salir'' de Abner como inteligencia militar; en Ezequiel 33:31 la ''venida'' del pueblo al profeta es habitual. ''Entrada tuya'' en español preserva la cualidad activa y procesual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109524, 'spa', 'El diluvio cataclísmico de la era de Noé, que designa el juicio mundial de Dios ', 'El diluvio cataclísmico de la era de Noé, que designa el juicio mundial de Dios mediante el agua sobre todos los seres vivientes. Siempre lleva artículo (הַמַּבּוּל) excepto cuando se niega en el discurso del pacto («no habrá más diluvio», Gén 9:11, 15). Aparece en pares con מַיִם como aposición («diluvio de aguas», Gén 6:17; 7:6) y en construcciones temporales («después del diluvio», Gén 9:28; 10:1, 32; 11:10). El Salmo 29:10 extiende su uso poético: Yahvé «se sentó entronizado sobre el diluvio», imagen sobrecogedora de soberanía sobre las aguas primordiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109529, 'spa', 'Pisoteo y subyugación', 'Las traducciones multilingües enfatizan el aplastamiento violento. Isaías 18:2 y 7 describen a una nación temible caracterizada por su conquista aplastante de otros pueblos, mientras que 22:5 retrata un día en que la propia Jerusalén experimenta el terror de ser pisoteada en el juicio: una inversión de su destino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109530, 'spa', 'Manantial o fuente', 'La evidencia interlingüística identifica consistentemente fuentes o manantiales de agua. Las dos ocurrencias en Isaías prometen la provisión divina de manantiales para los sedientos durante el regreso del exilio, transformando lugares desolados en tierras bien regadas. Eclesiastés 12:6 utiliza la imagen de la fuente en su meditación poética sobre la fragilidad de la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109533, 'spa', 'Lo superlativo, la selección más fina de una categoría; siempre en estado constr', 'Lo superlativo, la selección más fina de una categoría; siempre en estado constructo o con sufijos, nunca en forma absoluta. Se aplica a la excelencia humana (Éx 15:4 «capitanes escogidos»; Dn 11:15 «tropas selectas»), a la calidad material (Is 37:24 «los cedros más selectos»; Jr 22:7 «cedros escogidos»; Ez 24:4–5 «lo mejor del rebaño»), al esplendor geográfico (Is 22:7 «los valles más selectos») y al honor social (Gn 23:6 «los sepulcros más distinguidos»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109543, 'spa', 'Esperanza frustrada', 'Las traducciones lo vierten uniformemente como ''esperanza'' con sufijos posesivos que reflejan a las partes decepcionadas: ''nuestra esperanza, su esperanza.'' Las tres apariciones bíblicas retratan esperanzas políticas fallidas: Judá confiando en Egipto (Isaías 20:5-6) y Gaza dependiendo de Tiro (Zacarías 9:5). Estos pasajes revelan la futilidad de confiar en alianzas humanas en lugar de en Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109545, 'spa', 'El estado objetivo de estar seguro o a salvo del peligro', 'El estado objetivo de estar seguro o a salvo del peligro. Isaías 32:18 promete al pueblo de Dios «moradas seguras», y Job 18:14 describe al impío arrancado de la «seguridad» de su tienda. Aquí el término pasa de la confianza relacional a la protección objetiva, lo que el español distingue claramente con «seguridad».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109546, 'spa', 'El acto abstracto de confiar o tener seguridad interior', 'El acto abstracto de confiar o tener seguridad interior. Este sentido dominante (11 apariciones) se concentra en los salmos y la literatura sapiencial: «En el temor de Yahvé hay fuerte confianza» (Pr 14:26), «Tú eres mi confianza desde mi juventud» (Sal 71:5) y «Bendito el hombre cuya confianza es Yahvé» (Jr 17:7). El español «confianza» captura plenamente este matiz relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109553, 'spa', 'El objeto concreto de la confianza', 'El objeto concreto de la confianza: la persona o cosa en la que se deposita la fe. Job 8:14 compara la confianza del impío con una telaraña, y Jeremías 2:37 advierte que los «objetos de confianza» de Israel fracasarán. El español «refugio» distingue este referente concreto del sentimiento abstracto del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109563, 'spa', 'Fortaleza, plaza fuerte', 'Fortaleza, plaza fuerte: Lugar fortificado, bastión defensivo o ciudad amurallada diseñada para la protección militar y la resistencia al asedio. La colocación característica עִיר מִבְצָר (''ciudad fortificada'') aparece en la narrativa histórica (Jos 10:20; 19:29, 35; 1 S 6:18; 2 R 3:19; 17:9; 18:8) y en los oráculos proféticos (Jer 4:5; 5:17; 8:14; 34:7). En el juicio profético, las fortalezas se convierten en símbolos de confianza mal depositada: Dios destruye las defensas en las que Israel confiaba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109585, 'spa', 'Nombre propio', 'Este nombre propio aparece de forma consistente en las traducciones como transliteración: ''Mibsam, Mivsam'', con variaciones menores. Identifica a dos individuos distintos en las genealogías bíblicas: uno de la línea de Ismael, representando las tribus árabes, y otro del linaje de Simeón. Ambas apariciones cumplen una función primordialmente genealógica, preservando las líneas familiares en los registros históricos de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109589, 'spa', 'Tocado sacerdotal', 'El tocado sacerdotal aparece cuatro veces en las instrucciones de Éxodo y Levítico. Dios mandó a Moisés hacer «gorros» para los hijos de Aarón como parte de sus vestiduras sagradas (Éx 28:40). En la ordenación, Moisés puso «gorros» a los hijos de Aarón (Lv 8:13). La ceremonia de investidura incluía ceñirlos y atarles «gorros» (Éx 29:9). Las vestiduras terminadas incluían «los gorros de lino», literalmente «los hermosos tocados» (Éx 39:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109590, 'spa', 'Dones selectos, frutos preciados', 'Lo más fino y excelente del mundo natural, entendido como regalo divino. En la bendición de Moisés (Dt 33:13-16), el término aparece en cinco frases constructas sucesivas: ''lo excelente del cielo'', ''del sol'', ''de la luna'', ''de los montes antiguos'' y ''de la tierra y su plenitud'', cada una nombrando una dimensión de la abundancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109594, 'spa', 'Megido (ciudad)', 'Ciudad fortificada de gran importancia en el valle de Jezreel, situada en el paso estratégico de la cordillera del Carmelo que controlaba la antigua Vía Maris. Aparece entre las conquistas de Josué (Jos 12:21) y las ciudades asignadas a Manasés pero no conquistadas (Jos 17:11; Jue 1:27). Fue escenario de la victoria de Débora y Barac sobre Sísara (Jue 5:19), una de las ciudades administrativas y de carros de Salomón (1 Re 9:15), y el lugar donde murió el rey Josías (2 Re 23:29-30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109602, 'spa', 'Migdol (topónimo)', 'La ciudad fronteriza egipcia de Migdol, ubicada en el límite noreste de Egipto, identificada con el copto Meschtol y el egipcio Makthel. Como estación del Éxodo, señala el lugar donde Israel acampó antes del cruce del mar (Éx 14:2; Nm 33:7). En el corpus profético, Jeremías se dirige a judíos que habitan ''en Migdol'' (Jer 44:1; 46:14), mientras Ezequiel emplea el merismo ''desde Migdol hasta Sevene'' (Ez 29:10; 30:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109605, 'spa', 'Estructura alta y fortificada para defensa, vigilancia o protección urbana — el ', 'Estructura alta y fortificada para defensa, vigilancia o protección urbana — el sentido principal en 44 apariciones. Desde la soberbia de Babel (Gn 11:4) hasta las fortificaciones de Ezequías (2 Cr 32:5), la torre simboliza tanto la ambición humana como el refugio divino (Pr 18:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109611, 'spa', 'La palabra migdal funcionando como parte de un nombre propio de lugar', 'La palabra migdal funcionando como parte de un nombre propio de lugar: Migdal-Eder (''Torre del Rebaño'', Mi 4:8), Migdal-Gad, Migdal-El. Aquí el sustantivo común se ha fosilizado en topónimo. Las traducciones al español frecuentemente conservan el compuesto (''torre de''), preservando la etimología arquitectónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109630, 'spa', 'Plataforma elevada de madera o podio para la proclamación pública — uso único en', 'Plataforma elevada de madera o podio para la proclamación pública — uso único en Nehemías 8:4, donde Esdras lee la Torá al pueblo reunido. La altura arquitectónica de una torre se transforma en elevación retórica. No se trata de una estructura defensiva, sino de un estrado construido para la lectura solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109634, 'spa', 'Obsequios preciosos', 'Regalos de alto valor, presentados frecuentemente en contextos de honor, tributo o intercambio diplomático. Las glosas interlingüísticas («costly gifts», «precious things», «treasures») destacan uniformemente el valor material. Se encuentran en narrativas de entrega de obsequios desde la época patriarcal hasta la monarquía, siempre denotando artículos de valor excepcional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109635, 'spa', 'Pueblo y territorio', 'Nombre propio que designa tanto un grupo étnico descendiente de Jafet como un territorio geográfico, con protagonismo destacado en la profecía escatológica de Ezequiel. Las glosas multilingües mantienen el nombre propio sin traducción, conforme a su función como identificador geográfico y étnico en contextos tanto genealógicos como proféticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109636, 'spa', 'Terror, pavor, espanto', 'Terror, pavor u objeto de temor. Las ocho apariciones comparten el mismo sentido nuclear, variando desde el pavor abstracto (Is 31:9) hasta la causa concreta del espanto (Jer 20:4, ''te haré terror para ti mismo''). Ligada al estribillo de Jeremías magor missabib, ''terror por todas partes'' (Jer 6:25; 20:3, 10; 46:5; 49:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109640, 'spa', 'Peregrinación, extranjería', 'El acto o estado de peregrinar: vivir temporalmente como forastero o residente extranjero en una tierra que no es posesión permanente propia. Se emplea predominantemente en la fuente sacerdotal para describir la condición de extranjería de los patriarcas en Canaán: «la tierra de tus peregrinaciones» (Gn 17:8; 28:4; 36:7; 37:1; Éx 6:4; Ez 20:38). También en sentido temporal: los «años de peregrinación» de Jacob (Gn 47:9) y la «casa de peregrinación» del salmista (Sal 119:54).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109646, 'spa', 'Morada, habitación', 'Lugar concreto de residencia o habitación, sin énfasis en la dimensión de temporalidad o extranjería. En Job 18:19, el impío no tiene sobreviviente «en sus moradas», y en Salmo 55:15 se pide que la muerte sobrevenga a los enemigos «en su morada». El sentido se desplaza de la peregrinación abstracta hacia un lugar tangible de residencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109656, 'spa', 'rollo, pergamino escrito — Un documento enrollado de papiro o cuero utilizado pa', 'rollo, pergamino escrito — Un documento enrollado de papiro o cuero utilizado para registrar oráculos proféticos, instrucciones divinas u otros textos formales. Domina la narrativa de Jeremías 36, donde el sustantivo aparece dieciséis veces mientras el rollo de Baruc es escrito, leído, confiscado, quemado y reescrito. También designa el rollo visionario que Ezequiel recibe la orden de comer (Ez 2:9-3:3) y el rollo volador de maldición de Zacarías (Zac 5:1-2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109662, 'spa', 'Entregar u otorgar', 'Las glosas multilingües muestran un rango semántico desde ''entregó, puso en manos de'' hasta ''concederá, otorgará''. Génesis 14:20 alaba a Dios por entregar a los enemigos en poder de Abraham. Proverbios 4:9 promete que la sabiduría otorgará honra, mientras que Oseas 11:8 revela el pathos divino: el corazón de Dios resistiéndose a entregar al amado Israel al juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109663, 'spa', 'El sentido dominante en 60 apariciones', 'El sentido dominante en 60 apariciones: escudo o broquel defensivo usado en combate, y por extensión metafórica, Dios como protector y defensa del creyente. Los usos militares concretos abarcan Jueces 5:8, 2 Samuel 1:21, Nahúm 2:3 y los pasajes de arsenal en Crónicas. El registro metafórico — ''El SEÑOR es mi escudo'' (Gn 15:1; Sal 3:3; 18:2, 30) — es omnipresente en los Salmos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109671, 'spa', 'En Proverbios 6', 'En Proverbios 6:11 y 24:34, magen parece significar un hombre armado o portador de escudo: la pobreza viene sobre el perezoso ''como un hombre armado''. Aquí el escudo representa metonímicamente al guerrero que lo porta. Se trata de una metonimia compacta donde el arma sustituye al agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109680, 'spa', 'Una sola aparición en Oseas 4', 'Una sola aparición en Oseas 4:18 donde maginneha (''sus escudos'') se entiende como ''sus gobernantes'' o ''protectores'' — los líderes que deberían escudar a la comunidad pero en cambio aman la vergüenza. La metáfora se extiende de la defensa física al patronazgo político.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109685, 'spa', 'Plaga o pestilencia enviada como juicio divino sobre una población', 'Plaga o pestilencia enviada como juicio divino sobre una población. Abarca 23 de las 26 ocurrencias, centradas en los relatos del desierto en Números y la plaga del censo de David. El término implica causa sobrenatural y alcance comunitario: comunidades enteras son heridas. Éxodo 9:14 emplea el plural ''mis plagas'' cuando Dios advierte al faraón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109688, 'spa', 'Gran matanza o derrota militar devastadora, con énfasis en las bajas masivas en ', 'Gran matanza o derrota militar devastadora, con énfasis en las bajas masivas en batalla. Se usa en 1 Samuel 4:17 para la derrota filistea en Afec (donde se capturó el arca), en 2 Samuel 17:9 para la carnicería prevista en la rebelión de Absalón, y en 2 Samuel 18:7 para el enorme costo de la batalla en el bosque.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109700, 'spa', 'Sierra de corte', 'Sierra utilizada para cortar piedra o madera, presente tanto en contextos de construcción (el corte de piedra para el templo de Salomón) como en pasajes más oscuros que describen la subyugación de pueblos conquistados. La evidencia multilingüe («saws», «saw», «sierra») la identifica sistemáticamente como herramienta de corte, aunque la naturaleza exacta de su uso en 2 Samuel 12:31 sigue siendo debatida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109704, 'spa', 'tierra de pastoreo urbana', 'El sentido técnico-legal dominante: tierra de pastoreo o ejido designado, adscrito a las ciudades levíticas para apacentar ganado. Esto representa 110 de las 115 ocurrencias, concentradas densamente en Josué 21, 1 Crónicas 6 y Números 35. El término aparece casi como fórmula: ''la ciudad y sus campos de pastoreo'' (Jos 21:11, 13). El alemán Weide-Land y el francés pâturage reflejan la función pastoril.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109709, 'spa', 'terreno abierto, espacio libre', 'Sentido más amplio de terreno abierto o espacio despejado junto a un asentamiento, enfatizando la ausencia de edificaciones más que el uso pastoril. Las descripciones visionarias de Ezequiel emplean esta acepción: el espacio abierto alrededor del santuario (Ez 45:2), el área libre para la ciudad (Ez 48:15, 17) y los ''arrabales'' que tiemblan ante la caída de Tiro (Ez 27:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109712, 'spa', 'expulsión, destierro', 'Posible lectura verbal conectada con la raíz גָּרַשׁ (''expulsar, echar''), que aflora en Ezequiel 36:5 donde la forma מִגְרָשׁ podría representar un infinitivo Qal con sentido de ''expulsión'' o ''despojo'' en lugar del sustantivo habitual. La glosa ''expulsarla'' diverge marcadamente de las glosas pastoriles del resto de ocurrencias. Probablemente se trate de una superposición homográfica, y algunos comentaristas enmiendan el texto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109720, 'spa', 'El uso más frecuente, que designa una prenda de vestir, generalmente una túnica ', 'El uso más frecuente, que designa una prenda de vestir, generalmente una túnica o manto exterior. Las vestiduras sacerdotales de Levítico 6:10 y el atuendo militar de 1 Samuel 17:38–39 emplean este sentido. La evidencia multilingüe converge: «túnica», «ropa» y «vestidura» en español apuntan a una prenda exterior, no a ropa interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109722, 'spa', 'Un uso raro en 2 Samuel 21', 'Un uso raro en 2 Samuel 21:20 (Ketib), donde la palabra parece indicar estatura o gran tamaño físico, describiendo a un hombre de altura extraordinaria. El Qeré ofrece otra lectura (מָדוֹן), y el paralelo de 1 Crónicas 20:6 usa מִדָּה «medida», lo que sugiere incertidumbre textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109728, 'spa', 'Uso único en Jueces 5', 'Uso único en Jueces 5:10, donde probablemente se refiere a telas ricamente teñidas, tapices o mantas de montar extendidas sobre asnos para cabalgar. El contexto del cántico de Débora, dirigido a quienes se sientan sobre asnos blancos sobre «tapices», apoya la interpretación como textil de lujo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109729, 'spa', 'El sentido abstracto de medida, dimensión o cantidad asignada', 'El sentido abstracto de medida, dimensión o cantidad asignada. En Job 11:9 describe la extensión inconmensurable de la sabiduría de Dios, y en Jeremías 13:25 la «porción de tus medidas»: la parte asignada a la infiel Judá. El español «medidas» confirma esta lectura cuantitativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109734, 'spa', 'desierto, región yerma', 'Territorio abierto deshabitado o terreno árido más allá de los límites de la tierra agrícola asentada, utilizado para pastoreo estacional pero carente de población permanente. Es el escenario principal de la peregrinación de Israel tras el Éxodo (Éx 15:22ss.), el dominio de criaturas salvajes (Job 24:5; Jr 2:24) y lugar de encuentro divino y proclamación profética (Is 40:3). El español desierto y el alemán Wüste reflejan la desolación y el vacío humano del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109759, 'spa', 'El sentido activo Qal y Piel de medir, que abarca 47 de 51 apariciones', 'El sentido activo Qal y Piel de medir, que abarca 47 de 51 apariciones. La visión del templo de Ezequiel (caps. 40-47) domina con la fórmula repetida ''y midió'', pero el verbo también aparece en Rut 3:15 (Boaz midiendo cebada), Éxodo 16:18 (midiendo el maná) y Números 35:5 (midiendo los ejidos de los levitas).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (109770, 'spa', 'La forma Nifal (pasiva) que significa ''ser medido'' o ''poder medirse'', usada tres', 'La forma Nifal (pasiva) que significa ''ser medido'' o ''poder medirse'', usada tres veces en la retórica profética sobre la inconmensurabilidad. Jeremías 31:37 y 33:22 declaran que el ejército del cielo ''no se puede medir'', y Oseas 1:10 dice que Israel será como arena que ''no se podrá medir''. Este sentido porta un peso teológico: lo que Dios multiplica excede toda capacidad humana de cuantificación.');